(function(){
  'use strict';
  var MOUNT_SELECTOR = '[data-storage-regalove-boxy-config]';
  var ASSET_FLAG = 'data-rb-loader-asset';
  var HTML_B64 = '';

  function decodeBase64Unicode(str){
    return decodeURIComponent(Array.prototype.map.call(atob(str), function(c){
      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
  }

  function appendHeadAsset(node){
    var clone = node.cloneNode(true);
    clone.setAttribute(ASSET_FLAG, '1');
    if (clone.tagName === 'LINK') {
      var href = clone.getAttribute('href') || '';
      if (href && document.head.querySelector('link[' + ASSET_FLAG + '][href="' + href.replace(/"/g, '\\"') + '"]')) return;
    }
    if (clone.tagName === 'STYLE') {
      var key = clone.textContent || '';
      var styles = document.head.querySelectorAll('style[' + ASSET_FLAG + ']');
      for (var i = 0; i < styles.length; i += 1) {
        if ((styles[i].textContent || '') === key) return;
      }
    }
    document.head.appendChild(clone);
  }

  function runScript(oldScript){
    var script = document.createElement('script');
    var type = oldScript.getAttribute('type');
    if (type) script.type = type;
    if (oldScript.src) {
      script.src = oldScript.src;
    } else {
      script.text = oldScript.textContent || oldScript.innerText || '';
    }
    Array.prototype.forEach.call(oldScript.attributes, function(attr){
      if (attr.name !== 'src' && attr.name !== 'type') script.setAttribute(attr.name, attr.value);
    });
    document.body.appendChild(script);
  }

  function mount(){
    var mount = document.querySelector(MOUNT_SELECTOR);
    var html, template, scripts, headNodes;
    if (!mount || mount.getAttribute('data-mounted') === '1') return;

    html = decodeBase64Unicode(HTML_B64);
    template = document.createElement('template');
    template.innerHTML = html;

    headNodes = template.content.querySelectorAll('style, link[rel="stylesheet"], link[rel="preconnect"], link[rel="canonical"], meta, title');
    Array.prototype.forEach.call(headNodes, function(node){
      appendHeadAsset(node);
      node.parentNode.removeChild(node);
    });

    scripts = Array.prototype.slice.call(template.content.querySelectorAll('script'));
    scripts.forEach(function(node){
      node.parentNode.removeChild(node);
    });

    mount.innerHTML = '';
    mount.appendChild(template.content.cloneNode(true));
    mount.setAttribute('data-mounted', '1');
    scripts.forEach(runScript);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mount);
  } else {
    mount();
  }
})();
